import React, { useState } from 'react';
import { Copy, Check, FileCode } from 'lucide-react';
import { TestRecord } from '../types';

interface XmlViewerProps {
  records: TestRecord[];
  loginName?: string;
}

export const XmlViewer: React.FC<XmlViewerProps> = ({ records, loginName = '' }) => {
  const [copied, setCopied] = useState(false);

  const fullXml = `<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by Slot TestData Generator Agent -->
<Test>
  <Key moduleID="${records[0]?.moduleID || '105359'}" loginName="${loginName}" />
  <Slot>
${records.map((r) => {
  if (r.formatType === 'SINGLE') {
    return `    <!-- Case: ${r.caseName} -->\n    <Spin stage="${r.stage}" comment="${r.comment}">\n      <PreGen batch="${r.baseBatch}" index="${r.baseIndex}" />\n    </Spin>`;
  } else {
    return `    <!-- Case: ${r.caseName} (Double PreGen Nested Bonus) -->\n    <Spin stage="BaseGame" comment="${r.comment}">\n      <PreGen batch="${r.baseBatch}" index="${r.baseIndex}"></PreGen>\n      <Feature stage="Bonus">\n        <PreGen batch="${r.bonusBatch}" index="${r.bonusIndex}"></PreGen>\n      </Feature>\n    </Spin>`;
  }
}).join('\n\n')}
  </Slot>
</Test>`;

  const handleCopy = () => {
    navigator.clipboard.writeText(fullXml);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="bg-slate-950 border border-slate-800 rounded-xl overflow-hidden flex flex-col font-mono text-xs">
      <div className="bg-slate-900 px-4 py-2.5 border-b border-slate-800 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <FileCode className="w-4 h-4 text-emerald-400" />
          <span className="font-bold text-slate-200">Generated XML Specification (.testdata)</span>
        </div>
        <button
          onClick={handleCopy}
          className="px-2.5 py-1 rounded bg-slate-800 hover:bg-slate-700 text-slate-300 text-[11px] font-semibold transition flex items-center gap-1.5"
        >
          {copied ? <Check className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5" />}
          {copied ? 'XML Copied!' : 'Copy XML'}
        </button>
      </div>

      <div className="p-4 overflow-x-auto max-h-[380px] text-slate-300 leading-relaxed text-[11px]">
        <pre className="whitespace-pre">{fullXml}</pre>
      </div>
    </div>
  );
};
